import json
from types import SimpleNamespace
from pydantic import BaseModel, Field, ValidationError

# The sandbox has no network or API key, so FakeOpenAI stands in for openai.OpenAI().
# Like the real API, JSON mode (response_format={"type": "json_object"}) only works when
# a message mentions JSON, and only then is the reply guaranteed to be valid JSON.
class _Completions:
    def __init__(self):
        self.last_request = None

    def create(self, model, messages, response_format=None, **kwargs):
        self.last_request = {"model": model, "messages": messages, "response_format": response_format}
        if response_format != {"type": "json_object"}:
            text = "Sure! I'd give it 4 out of 5 - clear and practical, but a bit dated."
        elif not any("json" in m["content"].lower() for m in messages):
            raise ValueError("JSON mode requires the word 'JSON' in one of the messages")
        else:
            text = json.dumps({
                "title": "Automate the Boring Stuff with Python",
                "rating": 4,
                "pros": ["Clear explanations", "Practical projects"],
                "cons": ["No advanced topics", "Some outdated examples"],
                "recommended": True,
            })
        return SimpleNamespace(choices=[SimpleNamespace(message=SimpleNamespace(content=text))])


class FakeOpenAI:
    def __init__(self):
        self.chat = SimpleNamespace(completions=_Completions())


class BookReview(BaseModel):
    title: str
    rating: int = Field(ge=1, le=5)
    pros: list[str]
    cons: list[str]
    recommended: bool


def analyze_review(client, review_text):
    """Ask the model for JSON matching BookReview and parse it into a BookReview."""
    response = client.chat.completions.create(
        model="gpt-4o-mini",
        response_format={"type": "json_object"},
        messages=[
            {"role": "system", "content": "Analyze the book review. Reply in JSON with the keys "
                                          "title, rating (1-5), pros, cons and recommended."},
            {"role": "user", "content": review_text},
        ],
    )
    return BookReview.model_validate_json(response.choices[0].message.content)


review_text = ("Automate the Boring Stuff with Python is excellent for beginners. Clear explanations "
               "and practical projects. However, it doesn't cover advanced topics and some examples are outdated.")
review = analyze_review(FakeOpenAI(), review_text)
print(review)
